#include <boost/numeric/interval.hpp>
#include <boost/numeric/interval/utility.hpp>
#include <array>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <queue>
using namespace std;using boost::numeric::interval;using boost::numeric::lower;using boost::numeric::upper;using I=interval<double>;
struct AD{I v;array<I,3>g;array<array<I,3>,3>h;AD(double x=0):v(x){for(auto&z:g)z=I(0);for(auto&r:h)for(auto&z:r)z=I(0);}AD(I x):v(x){for(auto&z:g)z=I(0);for(auto&r:h)for(auto&z:r)z=I(0);}};AD var(I x,int k){AD a(x);a.g[k]=I(1);return a;}AD operator+(AD a,const AD&b){a.v+=b.v;for(int i=0;i<3;i++){a.g[i]+=b.g[i];for(int j=0;j<3;j++)a.h[i][j]+=b.h[i][j];}return a;}AD operator-(AD a,const AD&b){a.v-=b.v;for(int i=0;i<3;i++){a.g[i]-=b.g[i];for(int j=0;j<3;j++)a.h[i][j]-=b.h[i][j];}return a;}AD operator*(const AD&a,const AD&b){AD z;z.v=a.v*b.v;for(int i=0;i<3;i++){z.g[i]=a.g[i]*b.v+a.v*b.g[i];for(int j=0;j<3;j++)z.h[i][j]=a.h[i][j]*b.v+a.g[i]*b.g[j]+a.g[j]*b.g[i]+a.v*b.h[i][j];}return z;}AD scale(I k,const AD&a){AD z=a;z.v*=k;for(int i=0;i<3;i++){z.g[i]*=k;for(int j=0;j<3;j++)z.h[i][j]*=k;}return z;}AD inv(const AD&a){AD z;I v2=a.v*a.v,v3=v2*a.v;z.v=I(1)/a.v;for(int i=0;i<3;i++){z.g[i]=-a.g[i]/v2;for(int j=0;j<3;j++)z.h[i][j]=I(2)*a.g[i]*a.g[j]/v3-a.h[i][j]/v2;}return z;}AD operator/(const AD&a,const AD&b){return a*inv(b);}AD sqrta(const AD&a){AD z;z.v=sqrt(a.v);I den=I(2)*z.v,den3=I(4)*z.v*z.v*z.v;for(int i=0;i<3;i++){z.g[i]=a.g[i]/den;for(int j=0;j<3;j++)z.h[i][j]=a.h[i][j]/den-a.g[i]*a.g[j]/den3;}return z;}AD powi(AD a,int n){AD z(1.0);for(int i=0;i<n;i++)z=z*a;return z;}
struct Term{array<int,4>e;double cL,cU,hL,hU;};static const Term T[]={
{{2,2,0,0},0.04822142787987651,0.04822142787987652,0.013888888888888886,0.013888888888888891},{{2,0,2,0},0.05333608476307319,0.0533360847630732,0.013888888888888886,0.013888888888888891},{{1,2,1,0},0.11385707390148077,0.1138570739014808,0.027777777777777773,0.027777777777777783},{{1,1,1,1},0.34286799970231563,0.34286799970231574,0.07856742013183860,0.07856742013183864},{{1,0,3,0},0.06204319383393707,0.06204319383393708,0.013888888888888886,0.013888888888888891},{{0,2,2,0},0.06563564602160425,0.06563564602160428,0.013888888888888886,0.013888888888888891},{{0,2,0,2},0.13577211811522816,0.1357721181152282,0.027777777777777773,0.027777777777777783},{{0,1,2,1},0.2940921349879692,0.2940921349879693,0.05892556509887894,0.05892556509887898},{{0,0,4,0},0.017687575726200232,0.01768757572620024,0.0034722222222222215,0.003472222222222223},{{0,0,2,2},0.14600143188162154,0.1460014318816216,0.027777777777777773,0.027777777777777783}};
AD rho(array<AD,3>y){array<AD,4>Y={y[0],y[1],y[2],AD(1.0)-y[0]-y[1]-y[2]},c={sqrta(Y[0]),sqrta(Y[1]),sqrta(Y[2]),sqrta(Y[3])};AD C(0),H(0);for(auto&t:T){AD m(1);for(int i=0;i<4;i++)m=m*powi(c[i],t.e[i]);C=C+scale(I(t.cL,t.cU),m);H=H+scale(I(t.hL,t.hU),m);}return scale(I(4.0/3.7183448981203875),C/sqrta(H));}
struct Box{array<double,3>l,u;double ub;};struct Cmp{bool operator()(Box const&a,Box const&b)const{return a.ub<b.ub;}};
static array<double,3> x0={0.063925514399,0.225843540948,0.438542296078};static const double rr=5e-4;static array<double,3> SL={x0[0]-rr,x0[1]-rr,x0[2]-rr},SU={x0[0]+rr,x0[1]+rr,x0[2]+rr};
bool insideS(const Box&b){for(int i=0;i<3;i++)if(b.l[i]<SL[i]||b.u[i]>SU[i])return false;return true;}
double UB(Box const&b){array<AD,3>X,C;for(int i=0;i<3;i++){X[i]=var(I(b.l[i],b.u[i]),i);double m=.5*(b.l[i]+b.u[i]);C[i]=var(I(m),i);}AD RX=rho(X),RC=rho(C);double ub=upper(RC.v);for(int i=0;i<3;i++){double ga=max(fabs(lower(RX.g[i])),fabs(upper(RX.g[i])));ub += ga*.5*(b.u[i]-b.l[i]);}return min(ub,upper(RX.v));}
int main(){const double best=0.71753326806113;Box r{{0.02,0.15,0.35},{0.12,0.30,0.55},0};r.ub=UB(r);priority_queue<Box,vector<Box>,Cmp>pq;pq.push(r);long long n=0,skip=0;double skipub=0;while(!pq.empty()){Box b=pq.top();pq.pop();if(b.ub<=best){cout<<setprecision(17)<<"CERTIFIED_RING nodes "<<n<<" upper "<<b.ub<<" skipped "<<skip<<" skipped_ub "<<skipub<<"\n";return 0;}if(insideS(b)){skip++;skipub=max(skipub,b.ub);continue;}int k=0;double sc=-1;for(int i=0;i<3;i++){double w=b.u[i]-b.l[i];bool cross=(b.l[i]<SL[i]&&SL[i]<b.u[i])||(b.l[i]<SU[i]&&SU[i]<b.u[i]);double z=w*(cross?10:1);if(z>sc){sc=z;k=i;}}double mid=.5*(b.l[k]+b.u[k]);if(b.l[k]<SL[k]&&SL[k]<b.u[k])mid=SL[k];else if(b.l[k]<SU[k]&&SU[k]<b.u[k])mid=SU[k];for(int side=0;side<2;side++){Box q=b;if(!side)q.u[k]=mid;else q.l[k]=mid;q.ub=UB(q);if(q.ub>best)pq.push(q);}n++;if(n%100000==0)cerr<<n<<" top "<<(pq.empty()?best:pq.top().ub)<<" heap "<<pq.size()<<" skip "<<skip<<"\n";if(n>5000000){cout<<"INCOMPLETE "<<n<<" top "<<(pq.empty()?best:pq.top().ub)<<" heap "<<pq.size()<<"\n";return 2;}}
cout<<"CERTIFIED_RING_EMPTY\n";}
